    pos = 0
    while pos <= n:
        # Find the next non-blocked position >= pos
        while pos <= n and pos in blocked:
            pos += 1

        if pos > n:
            return False  # Can't place a lamp at pos

        # Place a lamp at pos, it covers [pos, pos+l]
        pos += l
    return True

# Calculate the minimum cost for a given lamp type (power l)
