    pos = 0
    count = 0
    while pos <= n:
        # Find the next non-blocked position >= pos
        while pos <= n and pos in blocked:
            pos += 1

        if pos > n:
            return float('inf')  # Can't place a lamp at pos

        count += 1
        pos += l
    return count * costs[l-1]

