    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    p = list(map(int, data[1:1+n]))

    # Count records in original sequence
    original_records = count_records(p)

    # Find elements that are not records
    non_record_elements = []
    for i, val in enumerate(p):
        # Check if val is a record
        is_record = False
        max_so_far = -1
        for j in range(i):
            if p[j] > max_so_far:
                max_so_far = p[j]
        if val > max_so_far:
            is_record = True

        if not is_record:
            non_record_elements.append(val)

    # If there are non-record elements, remove the smallest one
    if non_record_elements:
        print(min(non_record_elements))
    else:
        # All elements are records, remove the smallest one
        print(min(p))

