import sys

def is_good_sequence(seq):
    """Check if a sequence is good"""
    n = len(seq)
    if n == 0:
        return True

    # Set of elements for quick lookup
    elements = set(seq)

    # Check each element
    for i in range(n):
        found = False
        for d in range(32):  # Powers of two up to 2^31
            power_of_two = 1 << d
            partner = power_of_two - seq[i]
            if partner in elements:
                found = True
                break
        if not found:
            return False
    return True

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Try to keep as many elements as possible
    # We'll try to remove elements one by one to see if we can make it good

    # Start with the full sequence
    best = n

    # Try removing one element at a time
    for i in range(n):
        new_seq = a[:i] + a[i+1:]
        if is_good_sequence(new_seq):
            best = min(best, n - 1)
            break  # We found the minimum, can't get better than n-1

    # If we couldn't find a solution with n-1 elements, try removing two elements
    if best == n:
        for i in range(n):
            for j in range(i+1, n):
                new_seq = a[:i] + a[i+1:j] + a[j+1:]
                if is_good_sequence(new_seq):
                    best = min(best, n - 2)
                    break
            if best == n - 1:
                break

    print(best)

if __name__ == "__main__":
    solve()
"}

