for _ in range(m):
    u, v, c = map(int, input().split())
    roads.append((u-1, v-1, c))  # 0-indexed

# Build the system of equations: x_u XOR x_v = c
# We want to find x_i (0 or 1) for each city i

# Matrix where each row represents an equation
# Columns 0..n-1 are coefficients, column n is the constant term
matrix = []
for u, v, c in roads:
    row = [0] * (n + 1)
    row[u] = 1
    row[v] = 1
    row[n] = c
    matrix.append(row)

# Gaussian elimination over GF(2)
def solve_gf2(matrix, n_vars):
    rank = 0
    for col in range(n_vars):
        # Find pivot
        pivot = -1
        for row in range(rank, len(matrix)):
            if matrix[row][col] == 1:
                pivot = row
                break

        if pivot == -1:
            continue  # No pivot in this column

        # Swap rows
        matrix[rank], matrix[pivot] = matrix[pivot], matrix[rank]

        # Eliminate this column in other rows
        for row in range(len(matrix)):
            if row != rank and matrix[row][col] == 1:
                for c in range(col, n_vars + 1):
                    matrix[row][c] ^= matrix[rank][c]

        rank += 1

    # Check for inconsistency
    for row in range(rank, len(matrix)):
        if matrix[row][n_vars] == 1:
            return None  # Inconsistent

    # Back-substitute to find solution
    solution = [0] * n_vars
    for row in range(rank):
        # Find pivot column
        pivot_col = -1
        for col in range(n_vars):
            if matrix[row][col] == 1:
                pivot_col = col
                break

        if pivot_col == -1:
            continue

        # Solve for the pivot variable
        solution[pivot_col] = matrix[row][n_vars]
        for col in range(pivot_col + 1, n_vars):
            solution[pivot_col] ^= solution[col] * matrix[row][col]

    return solution

solution = solve_gf2(matrix, n)
if solution is None:
    print("Impossible")
else:
    print(n)
    print(' '.join(map(str, [i+1 for i in range(n) if solution[i]])))
