import sys

def is_permutation(compression, m):
    """Check if compression array is a permutation of length m"""
    if len(compression) != m:
        return False

    # Check if it contains exactly one of each integer from 1 to m
    freq = [0] * (m + 1)
    for val in compression:
        if 1 <= val <= m:
            freq[val] += 1

    for i in range(1, m + 1):
        if freq[i] != 1:
            return False

    return True

