        for k in range(1, n + 1):
            # Compute compression array
            compression = []
            for i in range(n - k + 1):
                window = a[i:i+k]
                compression.append(min(window))

            m = n - k + 1
            if is_permutation(compression, m):
                result.append('1')
            else:
                result.append('0')

        results.append(''.join(result))

    sys.stdout.write('\n'.join(results))

