def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return
    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1

# Read input
t = int(input())
results = []

for _ in range(t):
    n, x, m = map(int, input().split())
    parent = list(range(n + 1))
    rank = [1] * (n + 1)

    for _ in range(m):
        l, r = map(int, input().split())
        # Union all positions in [l, r]
        for i in range(l, r + 1):
            for j in range(i + 1, r + 1):
                union(parent, rank, i, j)

    # Find root of x
    root_x = find(parent, x)

    # Count how many positions are in the same component as x
    count = 0
    for i in range(1, n + 1):
        if find(parent, i) == root_x:
            count += 1

    results.append(str(count))

print("\n".join(results))

