def smallest_prime_factors(n):
    """Return an array where spf[i] is the smallest prime factor of i."""
    spf = [0] * (n + 1)
    spf[0] = spf[1] = 1
    for i in range(2, n + 1):
        if spf[i] == 0:
            spf[i] = i
            for j in range(i * 2, n + 1, i):
                if spf[j] == 0:
                    spf[j] = i
    return spf

def solve():
    n = int(input())

    # Find smallest prime factors
    spf = smallest_prime_factors(n)

    # Find all prime numbers
    primes = [i for i in range(2, n + 1) if spf[i] == i]

    # Assign colors: primes get consecutive colors starting from 1,
    # composites get the color of their smallest prime factor
    color = [0] * (n + 1)
    for i, prime in enumerate(primes):
        color[prime] = i + 1

    for i in range(2, n + 1):
        if spf[i] == i:
            # i is prime, already handled
            continue
        color[i] = color[spf[i]]

    # Output a_2, a_3, ..., a_n
    print(' '.join(map(str, color[2:n+1])))

