import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    if n < 3:
        print(-1)
        return
    prices = [int(next(it)) for _ in range(n)]

    # Adjacency set
    adj = [set() for _ in range(n)]
    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].add(v)
        adj[v].add(u)

    min_sum = float('inf')
    # For each edge (u,v), check if they share common neighbor
    # But we also need w different from u,v
    for u in range(n):
        neighbors = adj[u]
        if len(neighbors) < 2:
            continue
        for v in neighbors:
            if v <= u:
                continue
            # u < v
            # Check any common neighbor of u and v different from u,v
            for w in adj[u]:
                if w == u or w == v:
                    continue
                if w in adj[v]:
                    # Found triangle
                    s = prices[u] + prices[v] + prices[w]
                    if s < min_sum:
                        min_sum = s
                    break

    if min_sum != float('inf'):
        print(min_sum)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
"}

