import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    max_n = n
    # Precompute smallest prime factor
    spf = list(range(max_n + 1))
    for i in range(2, int(max_n**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_n + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def get_prime_factors(x):
        """Return a set of prime factors of x"""
        if x == 1:
            return set()
        factors = set()
        while x > 1:
            p = spf[x]
            factors.add(p)
            while x % p == 0:
                x //= p
        return factors

    active = [False] * (n + 1)
    factor_map = defaultdict(list)  # map from prime factor -> list of collider indices active

    out_lines = []
    for _ in range(m):
        op = next(it)
        i = int(next(it))

        if op == '+':
            if active[i]:
                out_lines.append("Already on")
            else:
                prime_factors = get_prime_factors(i)
                conflict = None
                for p in prime_factors:
                    if factor_map[p]:
                        conflict = factor_map[p][0]
                        break

                if conflict is not None:
                    out_lines.append(f"Conflict with {conflict}")
                else:
                    out_lines.append("Success")
                    active[i] = True
                    if i == 1:
                        factor_map[1].append(i)
                    else:
                        for p in prime_factors:
                            factor_map[p].append(i)
        elif op == '-':
            if not active[i]:
                out_lines.append("Already off")
            else:
                out_lines.append("Success")
                active[i] = False
                if i == 1:
                    factor_map[1].remove(i)
                else:
                    for p in get_prime_factors(i):
                        factor_map[p].remove(i)

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
