import sys

def can_form(word, allowed_letters):
    """Check if a word can be formed using only the allowed letters"""
    return all(char in allowed_letters for char in word)

def solve():
    n = int(sys.stdin.readline())
    words = [sys.stdin.readline().strip() for _ in range(n)]

    max_length = 0

    # Try all 1-letter combinations
    for letter in "abcdefghijklmnopqrstuvwxyz":
        allowed_letters = {letter}
        total = 0
        for word in words:
            if can_form(word, allowed_letters):
                total += len(word)
        max_length = max(max_length, total)

    # Try all 2-letter combinations
    for i in range(26):
        for j in range(i + 1, 26):
            letter1 = chr(ord("a") + i)
            letter2 = chr(ord("a") + j)
            allowed_letters = {letter1, letter2}
            total = 0
            for word in words:
                if can_form(word, allowed_letters):
                    total += len(word)
            max_length = max(max_length, total)

    print(max_length)

if __name__ == "__main__":
    solve()

