import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Precompute smallest prime factors (SPF)
    spf = list(range(n + 1))
    for i in range(2, int(n**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, n+1, i):
                if spf[j] == j:
                    spf[j] = i

    # Get prime factors for each number
    prime_factors = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        if spf[i] == i:  # prime
            prime_factors[i].append(i)
        else:
            factors = set()
            x = i
            while x != 1:
                p = spf[x]
                factors.add(p)
                while x % p == 0:
                    x //= p
            prime_factors[i] = list(factors)

    # For each prime, track activated colliders
    prime_activated = {}
    activated = set()

    out_lines = []

    for _ in range(m):
        cmd = next(it)
        i = int(next(it))

        if cmd == "+":
            if i in activated:
                out_lines.append("Already on")
            else:
                # Check for conflict
                conflict = None
                for p in prime_factors[i]:
                    if p in prime_activated:
                        conflict = next(iter(prime_activated[p]))
                        break

                if conflict is not None:
                    out_lines.append(f"Conflict with {conflict}")
                else:
                    out_lines.append("Success")
                    activated.add(i)
                    for p in prime_factors[i]:
                        if p not in prime_activated:
                            prime_activated[p] = set()
                        prime_activated[p].add(i)
        else:  # "-"
            if i not in activated:
                out_lines.append("Already off")
            else:
                out_lines.append("Success")
                activated.remove(i)
                for p in prime_factors[i]:
                    prime_activated[p].remove(i)
                    if not prime_activated[p]:
                        del prime_activated[p]

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

