    activated = set()

    out_lines = []

    for _ in range(m):
        cmd = next(it)
        i = int(next(it))

        if cmd == "+":
            if i in activated:
                out_lines.append("Already on")
            else:
                # Check for conflict
                conflict = None
                for p in prime_factors[i]:
                    if p in prime_activated:
                        conflict = next(iter(prime_activated[p]))
                        break

                if conflict is not None:
                    out_lines.append(f"Conflict with {conflict}")
                else:
                    out_lines.append("Success")
                    activated.add(i)
                    for p in prime_factors[i]:
                        if p not in prime_activated:
                            prime_activated[p] = set()
                        prime_activated[p].add(i)
        else:  # "-"
            if i not in activated:
                out_lines.append("Already off")
            else:
                out_lines.append("Success")
                activated.remove(i)
                for p in prime_factors[i]:
                    prime_activated[p].remove(i)
                    if not prime_activated[p]:
                        del prime_activated[p]

    sys.stdout.write("\n".join(out_lines))

