    """Return list of digits of x from right to left (least significant to most significant)"""
    return [int(d) for d in str(x)][::-1]

def f(x, y):
    """Compute f(x, y)"""
    digits_x = digitize(x)
    digits_y = digitize(y)

    # Get the lengths
    len_x = len(digits_x)
    len_y = len(digits_y)

    # Result digits
    result = []

    # Alternate digits, starting with y's digit
    for i in range(max(len_x, len_y)):
        if i < len_y:
            result.append(digits_y[i])
