def compute_lcs(A, B):
    n, m = len(A), len(B)
    # dp[i][j] = LCS of A[0:i] and B[0:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if A[i-1] == B[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp

def max_similarity(A, B):
    n, m = len(A), len(B)
    dp = compute_lcs(A, B)

    max_score = -float('inf')

