import sys
from bisect import bisect_left, bisect_right

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    a = []
    for _ in range(n):
        a.append(int(next(it)))

    # Pre-process: count frequency of each value
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # For each value, store sorted list of indices (1-indexed)
    pos = {}
    for idx, num in enumerate(a, 1):
        if num not in pos:
            pos[num] = []
        pos[num].append(idx)

    # Process queries
    out = []
    for _ in range(m):
        l = int(next(it))
        r = int(next(it))
        count = 0

        # Only check values that appear at least x times in whole array and x <= (r-l+1)
        for x in freq:
            if freq[x] >= x and x <= (r - l + 1):
                # Check if x appears exactly x times in [l, r]
                if x in pos:
                    indices = pos[x]
                    # Use binary search to count occurrences in [l, r]
                    left = bisect_left(indices, l)
                    right_idx = bisect_right(indices, r)
                    if right_idx - left == x:
                        count += 1

        out.append(str(count))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
"}

