def can_use_letters(word, allowed_letters):
    """Check if a word can be formed using only the allowed letters."""
    return all(char in allowed_letters for char in word)

def solve():
    n = int(input())
    words = [input().strip() for _ in range(n)]

    # Try all pairs of letters (including pairs where both letters are the same)
    max_length = 0

    # Try all combinations of two letters (a, b) where a <= b to avoid duplicates
    for i in range(26):
        for j in range(i, 26):
            letter1 = chr(ord('a') + i)
            letter2 = chr(ord('a') + j)
            allowed_letters = {letter1, letter2}

            # Calculate total length of words that can use these letters
            total_length = 0
            for word in words:
                if can_use_letters(word, allowed_letters):
                    total_length += len(word)

            # Update maximum
            max_length = max(max_length, total_length)

    print(max_length)

solve()
