def lcs(s1, s2):
    """Compute LCS of two strings using dynamic programming"""
    n, m = len(s1), len(s2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            if s1[i] == s2[j]:
                dp[i+1][j+1] = dp[i][j] + 1
            else:
                dp[i+1][j+1] = max(dp[i+1][j], dp[i][j+1])

    return dp[n][m]

def solve():
    n, m = map(int, input().split())
    A = input().strip()
    B = input().strip()

    max_score = 0

    # Try all substrings of A
    for i in range(n):
        for j in range(i, n):
            C = A[i:j+1]
            len_C = j - i + 1

            # Try all substrings of B
            for k in range(m):
                for l in range(k, m):
                    D = B[k:l+1]
                    len_D = l - k + 1

                    # Compute LCS
                    lcs_len = lcs(C, D)

                    # Compute similarity score
                    score = 4 * lcs_len - len_C - len_D

                    if score > max_score:
                        max_score = score

    print(max_score)

solve()
