def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        l = int(next(it))
        r = int(next(it))

        colors = []
        for i in range(n):
            colors.append(int(next(it)))

        # Left socks are first l socks, right socks are next r socks
        left_socks = colors[:l]
        right_socks = colors[l:]

        # Count color occurrences
        from collections import defaultdict
        left_color_count = defaultdict(int)
        right_color_count = defaultdict(int)

        for c in left_socks:
            left_color_count[c] += 1

        for c in right_socks:
            right_color_count[c] += 1

        # Calculate extra socks
        extra_left = 0
        extra_right = 0

        for c in left_color_count:
            if left_color_count[c] > right_color_count.get(c, 0):
                extra_left += left_color_count[c] - right_color_count.get(c, 0)

        for c in right_color_count:
            if right_color_count[c] > left_color_count.get(c, 0):
                extra_right += right_color_count[c] - left_color_count.get(c, 0)

        # Total cost is number of extra socks
        print(extra_left + extra_right)

