def bfs_distance(tree, start, end):
    """Calculate the distance between start and end using BFS."""
    from collections import deque

    visited = {start: 0}
    queue = deque([start])

    while queue:
        node = queue.popleft()
        if node == end:
            return visited[node]

        for neighbor in tree[node]:
            if neighbor not in visited:
                visited[neighbor] = visited[node] + 1
                queue.append(neighbor)

    return -1  # Should never happen in a tree

def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))
    results = []

    for _ in range(t):
        n = int(next(data))
        a = int(next(data))
        b = int(next(data))
        da = int(next(data))
        db = int(next(data))

        tree = {}
        for _ in range(n - 1):
            u = int(next(data))
