            tree[v] = tree.get(v, []) + [u]

        distance = bfs_distance(tree, a, b)

        if distance <= da:
            results.append("Alice")
        elif db > da:
            results.append("Bob")
        else:
            results.append("Alice")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
