def solve():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))

    # dp[i][j] = number of ways to be at position j after i moves, without ever guessing the wrong box
    # We use a 2D list for DP
    dp = [[0] * (n + 1) for _ in range(m + 2)]  # i ranges from 0 to m+1

    # Base case: after 0 moves, we start at some position x
    for x in range(1, n + 1):
        dp[0][x] = 1

    # Fill DP table
    for i in range(0, m + 1):
        for j in range(1, n + 1):
            # Move to j-1, j, or j+1
            if i < m + 1:
                # After i moves, we can move to j-1, j, or j+1
                for dj in [-1, 0, 1]:
                    nj = j + dj
                    if 1 <= nj <= n:
                        if i % 2 == 0 and i > 0:
                            # After an odd number of moves (i odd), we have just made a guess
                            # The doll must not be at a_{(i+1)/2}
                            if nj != a[(i + 1) // 2 - 1]:
                                dp[i + 1][nj] += dp[i][j]
                        else:
                            # Before a guess, no restriction
                            dp[i + 1][nj] += dp[i][j]

    # Count all valid (x, y) pairs
    result = 0
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            if dp[m + 1][y] > 0:
                result += 1

    print(result)

solve()
