import sys
from collections import defaultdict

def parse_url(url):
    """Parse a URL into hostname and path"""
    # Split by '://' to get the rest
    parts = url.split('://', 1)
    if len(parts) != 2:
        return None, None

    # The first part is 'http', the second is the rest
    rest = parts[1]

    # Split by '/' to get hostname and path
    if '/' in rest:
        hostname, path = rest.split('/', 1)
    else:
        hostname = rest
        path = ""

    return hostname, path

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    n = int(data[0])
    urls = data[1:n+1]

    # Map from hostname to set of paths
    hostname_to_paths = defaultdict(set)

    for url in urls:
        hostname, path = parse_url(url)
        if hostname is not None and path is not None:
            hostname_to_paths[hostname].add(path)

    # Group hostnames by their set of paths
    path_set_to_hostnames = defaultdict(list)

    for hostname, path_set in hostname_to_paths.items():
        path_set_to_hostnames[frozenset(path_set)].append(hostname)

    # Filter groups with more than one hostname
    result = []
    for path_set, hostnames in path_set_to_hostnames.items():
        if len(hostnames) > 1:
            result.append(hostnames)

    # Output
    print(len(result))
    for group in result:
        print(' '.join(group))

if __name__ == "__main__":
    main()
"}

