def is_permutation(compression):
    """Check if the compression array is a permutation of its length."""
    m = len(compression)
    seen = set()
    for val in compression:
        if val < 1 or val > m:
            return False
        if val in seen:
            return False
        seen.add(val)
    return len(seen) == m

